// DraftIQ v0.9.38 — unified Available / Yahoo rankings board.
(function(){
let mode='yahoo';
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function key(n){try{return typeof keyName==='function'?keyName(n):String(n||'').toLowerCase().replace(/[^a-z0-9]/g,'')}catch{return String(n||'').toLowerCase().replace(/[^a-z0-9]/g,'')}}
function yr(n){return window.DraftIQYahooRank?.(n)||9999;}
function board(){const gone=typeof taken==='function'?taken():new Set();let rows=(window.DRAFTIQ_PLAYERS||[]).filter(p=>!gone.has(key(p[0])));if(mode==='yahoo')rows=rows.filter(p=>yr(p[0])<9999).sort((a,b)=>yr(a[0])-yr(b[0]));else rows=rows.map(p=>({p,score:typeof draftScore==='function'?draftScore(p):0,surv:typeof survival==='function'?survival(p):0})).sort((a,b)=>b.score-a.score);const pos=['ALL','QB','RB','WR','TE','DEF'];return `<div class="yahoo-rank-page"><div class="card yahoo-rank-hero"><div><div class="eyebrow">AVAILABLE PLAYERS</div><h2>Player Rankings</h2><p>${mode==='yahoo'?'Yahoo draft-room order. Keepers and drafted players are automatically removed.':'DraftIQ order based on projection, roster fit and pick urgency. Keepers and drafted players are automatically removed.'}</p><div class="rank-mode-toggle"><button class="${mode==='yahoo'?'on':''}" onclick="DraftIQRankMode('yahoo')">Yahoo Rankings</button><button class="${mode==='draftiq'?'on':''}" onclick="DraftIQRankMode('draftiq')">DraftIQ Rankings</button></div></div><div class="yahoo-rank-count"><strong>${rows.length}</strong><span>AVAILABLE</span></div></div><div class="card"><div class="yahoo-rank-tools"><input id="yahooRankSearch" placeholder="Search players…" oninput="DraftIQFilterYahooRanks()"><select id="yahooRankPos" onchange="DraftIQFilterYahooRanks()">${pos.map(x=>`<option>${x}</option>`).join('')}</select></div><table class="yahoo-rank-table"><thead>${mode==='yahoo'?'<tr><th>Yahoo</th><th>Player</th><th>Pos</th><th>Proj Pts</th></tr>':'<tr><th>DraftIQ</th><th>Player</th><th>Pos</th><th>Next Pick</th><th>Proj Pts</th></tr>'}</thead><tbody>${rows.map((x,i)=>{const p=mode==='yahoo'?x:x.p;return `<tr data-name="${esc(p[0]).toLowerCase()}" data-pos="${esc(p[1])}"><td class="yahoo-rank-num">${mode==='yahoo'?yr(p[0]):Math.round(x.score)}</td><td><b>${esc(p[0])}</b></td><td><span class="pill">${esc(p[1])}</span></td>${mode==='draftiq'?`<td><b>${Math.round(x.surv)}%</b></td>`:''}<td>${Number(p[3]||0).toFixed(1)}</td></tr>`}).join('')}</tbody></table></div></div>`;}
function render(){document.getElementById('app').innerHTML=board();document.body.classList.remove('command-active');}
window.DraftIQRankMode=function(m){mode=m;render();};
window.DraftIQFilterYahooRanks=function(){const q=(document.getElementById('yahooRankSearch')?.value||'').toLowerCase().trim(),pos=document.getElementById('yahooRankPos')?.value||'ALL';document.querySelectorAll('.yahoo-rank-table tbody tr').forEach(r=>{r.style.display=(!q||r.dataset.name.includes(q))&&(pos==='ALL'||r.dataset.pos===pos)?'':'none';});};
const baseView=window.view;window.view=function(v){if(v==='players'||v==='yahoo'){if(typeof nav==='function')nav('players');const next=typeof nextMineIncludingCurrent==='function'?nextMineIncludingCurrent():null;if(document.getElementById('status')&&typeof owner==='function'&&typeof fmtPick==='function')document.getElementById('status').innerHTML=`<b>${esc(owner(s.pick))}</b> on pick ${fmtPick(s.pick)}<br>${next?`Your next: <b>${fmtPick(next)}</b>`:'Draft complete'}`;render();return;}return baseView(v);};
})();